+    // Reproduction for the report "parallel walker occasionally hangs if
+    // visitor panics". Expected: run() returns by propagating the visitor's
+    // panic to the caller instead of hanging. (The report's version of this
+    // test used `#[should_panic(expected = "oops!")]`; the hang is the same,
+    // but that form also demands that the original payload is forwarded,
+    // which fails even with 1 thread where nothing hangs. Here the walk is
+    // wrapped in catch_unwind so that only the walk itself can satisfy it.)
+    #[test]
+    fn panic_in_parallel() {
+        let td = tmpdir();
+        wfile(td.path().join("foo.txt"), "");
+
+        let result = std::panic::catch_unwind(|| {
+            WalkBuilder::new(td.path())
+                .threads(40)
+                .build_parallel()
+                .run(|| Box::new(|_| panic!("oops!")));
+        });
+        assert!(
+            result.is_err(),
+            "a panic in the visitor should propagate out of run()"
+        );
+    }
+
